using MarketSphere.Domain.Entities.CRM;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace MarketSphere.Infrastructure.Persistence.Configurations.CRM;
public sealed class OpportunityConfiguration : IEntityTypeConfiguration<Opportunity> { public void Configure(EntityTypeBuilder<Opportunity> b) { b.ToTable("Opportunities", t => { t.HasCheckConstraint("CK_Opportunities_Probability", "[ProbabilityPercent] >= 0 AND [ProbabilityPercent] <= 100"); t.HasCheckConstraint("CK_Opportunities_Value", "[ExpectedValue] >= 0"); }); b.HasKey(x => x.OpportunityID); b.Property(x => x.OpportunityCode).HasMaxLength(30).IsRequired(); b.Property(x => x.OpportunityName).HasMaxLength(200).IsRequired(); b.Property(x => x.ExpectedValue).HasPrecision(18, 2); b.Property(x => x.Competitor).HasMaxLength(200); b.Property(x => x.LostReason).HasMaxLength(500); b.HasIndex(x => x.OpportunityCode).IsUnique(); b.HasIndex(x => new { x.Stage, x.OwnerEmployeeID, x.ExpectedCloseDate }); b.HasOne(x => x.Lead).WithMany().HasForeignKey(x => x.LeadID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Client).WithMany().HasForeignKey(x => x.ClientID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.OwnerEmployee).WithMany().HasForeignKey(x => x.OwnerEmployeeID).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Campaign).WithMany().HasForeignKey(x => x.CampaignID).OnDelete(DeleteBehavior.Restrict); } }
